\label{thm:upper}
Under \eqref{eq:periodic-kpp}--\eqref{eq:u0}, the following estimates
hold uniformly in $e\in\mathbb S^{d-1}$.
\begin{enumerate}
\item There is $C\geq1$ such that, with
$z_e(t,x)=p_e\cdot x-tH(p_e)+\kappa_d\log t$,
\begin{equation}\label{eq:upper-main}
 u(t,x)\leq C(1+z_e(t,x))\mathrm e^{-z_e(t,x)}
 \qquad(t\geq4,\ z_e(t,x)\geq0).
\end{equation}
\item For each $\theta\in(0,1)$ and $\rho\geq0$, there is
$C_{\theta,\rho}$ such that $u(t,x)<\theta$ whenever
\begin{equation}\label{eq:ray-upper}
 t\geq4,\quad |x-re|\leq\rho,\quad r\geq0,\quad
 r\geq w(e)t-\frac{d+2}{2\alpha_e}\log t+C_{\theta,\rho}.
\end{equation}
\end{enumerate}

\label{thm:axial}
Assume \eqref{eq:periodic-kpp}, \eqref{eq:u0} and
\eqref{eq:transverse-linearization}. Let $\lambda_*>0$ minimize
$[2(\cosh\lambda-1)+a_{\mathrm{eff}}]/\lambda$, put
$c_*=2\sinh\lambda_*$, and define
\begin{equation*}                   
 m_d(t)=c_*t-\frac{d+2}{2\lambda_*}\log t,\qquad t\geq2.
\end{equation*}
\begin{enumerate}
\item For each $\theta\in(0,1)$ there are $C_\theta,T_\theta$ such that
\begin{equation}\label{eq:axial-position}
 \left|\sup\{j\in\mathbb Z:u(t,j,0)\geq\theta\}-m_d(t)\right|
 \leq C_\theta\qquad(t\geq T_\theta).
\end{equation}
For these times, $u(t,j,0)\geq\theta$ whenever
$0\leq j\leq m_d(t)-C_\theta$.
\item For each $\theta\in(0,1)$ and $A\geq0$, all sufficiently large
$t$ admit $j_t\in\mathbb Z$ such that
\begin{equation}\label{eq:diffusive-section}
 |j_t-m_d(t)|\leq C_{\theta,A},\qquad
 \inf_{|y|\leq A\sqrt t}u(t,j_t,y)\geq\theta.
\end{equation}
\item For every $A\geq0$ and $\sigma>0$ there are positive constants
$b_{A,\sigma},B_{A,\sigma},T_{A,\sigma}$ such that, with
$\xi=j-m_d(t)$,
\begin{equation}\label{eq:axial-leading-edge}
 b_{A,\sigma}(1+\xi)\mathrm e^{-\lambda_*\xi}
 \leq u(t,j,y)\leq
 B_{A,\sigma}(1+\xi)\mathrm e^{-\lambda_*\xi}
\end{equation}
whenever $t\geq T_{A,\sigma}$, $1\leq\xi\leq\sigma\sqrt t$ and
$|y|\leq A\sqrt t$.
\end{enumerate}

\label{thm:critical-uniqueness}
Assume \eqref{eq:periodic-kpp}. Fix $n\in\mathbb S^{d-1}$, let
$\lambda>0$ minimize $H(\eta n)/\eta$, and put
$c=H(\lambda n)/\lambda$, $p=\lambda n$,
$D_n=\tfrac12n^{\mathsf T}\nabla^2H(p)n$ and
$\dot\phi_p=\left.\partial_\eta\phi_{\eta n}\right|_{\eta=\lambda}$.
Let $\Phi$ be a $\Gamma$-periodic pulsating profile in direction $n$
with speed $c$ and end states $1,0$, satisfying
\begin{equation}\label{eq:front-critical-upper}
 0<\Phi(s,x)\leq C(1+s)\mathrm e^{-\lambda s}
             \qquad(s\geq0,\ x\in\mathcal C).
\end{equation}
Then the following statements hold.
\begin{enumerate}
\item There are $A_\Phi>0$, $B_\Phi\in\mathbb R$ and $\varepsilon>0$ such
that, uniformly in the cell as $s\to+\infty$,
\begin{equation}\label{eq:critical-tail-expansion}
 \Phi(s,x)=\mathrm e^{-\lambda s}
 \left[(A_\Phi s+B_\Phi)\phi_p(x)-A_\Phi\dot\phi_p(x)
                                  +O(\mathrm e^{-\varepsilon s})\right],
\end{equation}
where
\begin{equation}\label{eq:critical-amplitude}
 A_\Phi=\frac1{D_n}\int_{\mathbb R}\mathrm e^{\lambda s}
       \sum_{x\in\mathcal C}\phi_p^*(x)
           \bigl(a(x)\Phi(s,x)-F(x,\Phi(s,x))\bigr)\,\mathrm d s.
\end{equation}
\item Every such profile is strictly decreasing in its first variable,
and any two such profiles differ only by a translation of that variable.
\end{enumerate}

\label{thm:selection}
Under the assumptions of Theorem~\ref{thm:axial}, there is a unique
critical pulsating profile $\Phi_*$ in direction $e_1$ with speed $c_*$
in the class \eqref{eq:front-critical-upper}, with $\lambda=\lambda_*$
and normalization $\Phi_*(0,0)=1/2$.
\begin{enumerate}
\item There is a bounded function $\zeta\in C^\infty([2,\infty))$
with $\zeta'(t)\to0$ such that, for each fixed $B\geq0$,
\begin{equation}\label{eq:profile-selection}
 \sup_{\substack{j\geq0\\ |y|\leq B}}
 |u(t,j,y)-\Phi_*(j-m_d(t)+\zeta(t),(j,y))|\to0.
\end{equation}
\item The first time derivative satisfies
\begin{equation}\label{eq:profile-time-derivative}
 \sup_{\substack{j\geq0\\ |y|\leq B}}
 \left|u_t(t,j,y)+c_*\partial_1\Phi_*
       (j-m_d(t)+\zeta(t),(j,y))\right|\to0
\end{equation}
for each fixed $B\geq0$.
\end{enumerate}

\label{lem:spectral}
\begin{enumerate}[label=\textup{(\roman*)}]
\item The function $H$ is real analytic, even, and superlinear, with
positive definite Hessian. For $H_0(p)=2\sum_i(\cosh p_i-1)$,
\begin{equation}\label{eq:H-comparison}
 H_0(p)+\min a\leq H(p)\leq H_0(p)+\max a.
\end{equation}
\item The operators $Q_p$ and $\widehat Q_p$ are Markov generators
related by time reversal with respect to $\pi_p$. Their mean
displacements, averaged over the stationary cell distribution,
are $-\nabla H(p)$ and $\nabla H(p)$, respectively. Both have
asymptotic covariance $\Sigma_p=\nabla^2H(p)$.
\end{enumerate}

\label{thm:quantitative-geometry}
\begin{enumerate}
\item The map $E(n)=v(n)/|v(n)|$ is a smooth diffeomorphism of the
sphere, with inverse $e\mapsto n_e=p_e/|p_e|$. There are $b_0,b_1>0$
such that
\begin{equation}\label{eq:quadratic-support-gap}
 b_0|n-n_e|^2\leq H(p(n))-p(n)\cdot v_e
                \leq b_1|n-n_e|^2
 \qquad(e,n\in\mathbb S^{d-1}).
\end{equation}
\item For fixed $C\in\mathbb R$, let
\begin{equation*}                                         
 \mathcal O_t(C)=\bigcap_{n\in\mathbb S^{d-1}}
 \{x\in\mathbb R^d:p(n)\cdot x\leq tH(p(n))-\kappa_d\log t+C\}.
\end{equation*}
For all sufficiently large $t$, this set contains zero in its interior.
Its radial function $r_t(e)=\sup\{r\geq0:re\in\mathcal O_t(C)\}$
satisfies, uniformly in $e$,
\begin{equation}\label{eq:radial-support-expansion}
 r_t(e)=w(e)t-\frac{\kappa_d}{\alpha_e}\log t
        +\frac C{\alpha_e}+O_C\!\left(\frac{(\log t)^2}{t}\right).
\end{equation}
Every normal attaining the radial minimum differs from $n_e$ by
$O_C(\log t/t)$.
\end{enumerate}

\label{lem:survival}
For either corrected scalar martingale $Y$ in
Lemma~\ref{lem:Markov-estimates}, with $Y_0=0$, fix a starting height
$r>0$ and set
$\tau=\inf\{s\geq0:r+Y_s\leq0\}$. Then
\begin{equation}\label{eq:survival}
 \mathbb P_x(\tau>t)\leq
       \min\{1,C(1+r)/\sqrt{1+t}\}.
\end{equation}

\label{lem:killed-kernel-upper}
The following bounds are uniform for $p\in\mathcal P$ and $b\in\mathbb R$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $d_{p,b}(t,x)>0$ and $d_{p,b}(s,y)>0$, then
\begin{equation}\label{eq:killed-kernel-upper}
 \mathsf K_p(s,t;x,y)
 \le C\frac{(1+d_{p,b}(t,x))_+(1+d_{p,b}(s,y))_+}
              {(1+t-s)^{d/2+1}}.
\end{equation}
\item If $d^\chi_{p,b}(t,x)>0$ and $d^\chi_{p,b}(s,y)>0$, then
\begin{equation}\label{eq:corrected-killed-kernel-upper}
 \mathsf K_{p,\chi}(s,t;x,y)
 \le C(C_0)\frac{(1+d^\chi_{p,b}(t,x))(1+d^\chi_{p,b}(s,y))}
 {(1+t-s)^{d/2+1}}.
\end{equation}
\end{enumerate}

\label{lem:longitudinal}
\begin{enumerate}
\item The heat kernel $\mathsf p_n(t,y)$ of $\Delta_{\mathbb Z^n}$ is positive
for $t>0$ and satisfies $\mathsf p_n(t,y)\leq C(1+t)^{-n/2}$. For each
fixed $A\geq0$, as $t\to\infty$,
\begin{equation}\label{eq:heat-local}
 \mathsf p_n(t,y)=(4\pi t)^{-n/2}\mathrm e^{-|y|^2/(4t)}
                 +O_A(t^{-(n+1)/2}),\qquad |y|\leq A\sqrt t.
\end{equation}
\item For each fixed $A\geq0$, with $s=j-c_*t$,
\begin{equation}\label{eq:signed-kernel}
 w_1(t,j)=\frac{(s+\delta_*)\mathrm e^{-s^2/(4D_*t)}}
                  {\sqrt{4\pi}D_*^{3/2}t^{3/2}}
              +O_A((1+|s|)t^{-2}),\qquad |s|\leq A\sqrt t,
\end{equation}
as $t\to\infty$. Moreover,
$Z(t,j)=\mathrm e^{-\lambda_*(j-c_*t)}w_1(t,j)$ solves
$Z_t=\Delta_{\mathbb Z}Z+aZ$.
\end{enumerate}

\label{lem:transverse-kernel}
\begin{enumerate}
\item The matrix $\Sigma_\perp$ is positive definite, and
\begin{equation}\label{eq:transverse-factorization}
 H(p_1,p')=2(\cosh p_1-1)+H_\perp(p'),\qquad H_\perp(0)=a.
\end{equation}
\item The kernel $K_\perp(s;y,z)$ of $\mathrm e^{s\mathcal A_\perp}$ on
$\mathbb Z^n$ is positive for $s>0$ and satisfies
\begin{equation}\label{eq:transverse-kernel-upper}
 \mathrm e^{-as}K_\perp(s;y,z)\leq C(1+s)^{-n/2}.
\end{equation}
For every fixed $A\geq0$, uniformly for $|y-z|\leq A\sqrt s$ and
$s\geq1$,
\begin{equation}\label{eq:transverse-kernel-local}
\begin{split}
 \mathrm e^{-as}K_\perp(s;y,z)
 &=\frac{|\mathcal C_\perp|\psi_\perp(y)\psi_\perp(z)}
         {(2\pi s)^{n/2}\sqrt{\det\Sigma_\perp}}\,
   \exp\!\left(-\frac{(y-z)^{\mathsf T}\Sigma_\perp^{-1}(y-z)}{2s}\right)\\
 &\quad+O_A(s^{-(n+1)/2}).
\end{split}
\end{equation}
The constants are uniform in the two cell residues.
\end{enumerate}

\label{lem:product-subsolution}
One can choose $\beta_\perp>0$, independently of $T$ and $y_0$, so
that $0<H_T\leq1$ for $t\geq0$ and the following hold.
\begin{enumerate}
\item Every solution of \eqref{eq:scalar-logistic} gives a subsolution
$q(t,j)H_T(t,y;y_0)$ of \eqref{eq:main}.
\item If $u_0(j_0,y_0)>0$, there are $T\geq1$ and
$\varepsilon>0$ such that the solution with
$q(0,j)=\varepsilon\1_{\{j_0\}}(j)$ satisfies
\begin{equation}\label{eq:product-comparison}
 u(T+t,j,y)\geq q(t,j)H_T(t,y;y_0)\qquad(t\geq0).
\end{equation}
\end{enumerate}

\label{lem:autonomous-leading-lower}
Let $Q$ solve $Q_t=\Delta_{\mathbb Z}Q+aQ-KQ^2$, $K>0$, with nonzero finitely
supported data $0\leq Q(0,\cdot)\leq a/K$. For every $A>0$, there
exist $c_0>0$ and $L_0,t_0\geq1$ such that
\begin{equation}\label{eq:autonomous-leading-lower}
 Q(t,j)\geq c_0t^{-3/2}s\mathrm e^{-\lambda_*s},\qquad s=j-c_*t,
\end{equation}
for $t\geq t_0$ and $L_0\leq s\leq A\sqrt t$.

\label{lem:delayed-pulse}
There exist $\varepsilon_*,\tau_*>0$, depending only on
$a,K,\beta,\mu$, such that, for $0<\varepsilon\leq\varepsilon_*$,
$\Psi(t,j)=\Phi_\varepsilon(r(t,j))$ takes values in $[0,a/K]$ and
satisfies
\begin{equation}\label{eq:delayed-pulse-subsolution}
    \Psi_t\leq\Delta_{\mathbb Z}\Psi+
               \left(a-\frac\beta{t+T}\right)\Psi-K\Psi^2,
\end{equation}
for $t\geq0$, $t+T\geq\tau_*$, almost everywhere at each site.

\label{prop:scalar-logarithmic-lower}
For every $\sigma>0$, there exist $\varepsilon,\eta>0$ and
$t_0\geq1$ such that, for all $t\geq t_0$,
\begin{equation}\label{eq:scalar-profile-lower}
 q(t,j)\geq\Phi_\varepsilon(r(t,j))
 \qquad\text{if }r(t,j)\leq\sigma\sqrt{t+T}.
\end{equation}
In particular,
\begin{equation}\label{eq:scalar-positive-seed}
 q\left(t,
       \left\lceil c_*t-b_\beta\log(t+T)+1\right\rceil\right)
       \geq\eta.
\end{equation}

\label{thm:rigidity}
Let $V:\mathbb R\times\mathbb Z^d\to(0,1)$ be an entire solution of
\eqref{eq:main}, and let $r=x\cdot n-ct$, where $|n|=1$ and $c>0$.
All limits and bounds below are uniform over $t\in\mathbb R$ and
$x\in\mathbb Z^d$ in the indicated regions. Suppose that, for some
$\lambda,b,B,R_0>0$,
\begin{equation}\label{eq:rigidity-hyp}
 \lim_{R\to\infty}\inf_{r\leq-R}V(t,x)=1,\qquad
 b(1+r)\mathrm e^{-\lambda r}\leq V(t,x)\leq B(1+r)\mathrm e^{-\lambda r}
 \quad(r\geq R_0).
\end{equation}
Then $V$ is a pulsating front, strictly increasing in time, and
\begin{equation}\label{eq:covariance}
 V(t+n\cdot\ell/c,x+\ell)=V(t,x)\qquad(\ell\in\Gamma).
\end{equation}

\label{lem:tail-source}
Let $\Phi$ be a pulsating profile with end states $1,0$ satisfying
\eqref{eq:front-critical-upper}. Then $g\geq0$, $g\not\equiv0$, and
\begin{enumerate}
\item For $k=0,1,2$,
\begin{equation}\label{eq:tail-source-derivatives}
 \max_{x\in\mathcal C}|\partial_s^kg(s,x)|\leq
 \begin{cases}
 C\mathrm e^{\lambda s},&s\leq0,\\
 C(1+s)^2\mathrm e^{-\lambda s},&s\geq0.
 \end{cases}
\end{equation}
\item The transform $\widehat g$ is analytic for
$|\operatorname{Re}z|<\lambda$. For every $0<\delta<\lambda$,
\begin{equation}\label{eq:tail-source-transform}
 \sup_{|\sigma|\leq\delta}
 \lVert \widehat g(\sigma+\mathrm i\tau)\rVert
       \leq\frac{C_\delta}{1+\tau^2}\qquad(\tau\in\mathbb R).
\end{equation}
\item The transform $\widehat v$ is analytic for
$0<\operatorname{Re}z<\lambda$ and satisfies
\begin{equation}\label{eq:tail-transform-equation}
 \mathcal M(z)\widehat v(z)=\widehat g(z).
\end{equation}
\end{enumerate}

\label{lem:critical-transform-gap}
For some $\delta_0\in(0,\lambda)$, $\mathcal M(z)$ is invertible on
$|\operatorname{Re}z|\leq\delta_0$, $z\ne0$.
For sufficiently large $|\operatorname{Im}z|$ in this strip,
\begin{equation}\label{eq:critical-resolvent-large}
 \lVert \mathcal M(z)^{-1}\rVert
       \leq\frac{C}{1+|\operatorname{Im}z|}.
\end{equation}
Near zero,
\begin{equation}\label{eq:critical-resolvent-local}
 \mathcal M(z)^{-1}
 =\frac{\phi_{p-zn}(\phi^*_{p-zn})^{\mathsf T}}{k(z)}
       +\mathcal R(z),\qquad
 k(z)=H(p-zn)-c(\lambda-z)=D_nz^2+O(z^3),
\end{equation}
where $\mathcal R$ is analytic.

\label{cor:arrival-times}
Assume the hypotheses of Theorem~\ref{thm:axial}. Fix $B\geq0$ and
$0<\theta_-<\theta_+<1$.
\begin{enumerate}
\item There are $\delta>0$ and $t_0$ such that
\begin{equation}\label{eq:temporal-transversality}
 u_t(t,j,y)\geq\delta
 \quad\hbox{if }t\geq t_0,\ j\geq0,\ |y|\leq B,
                  \ \theta_-\leq u(t,j,y)\leq\theta_+.
\end{equation}
For all sufficiently large $j$, every $\theta\in[\theta_-,\theta_+]$
is attained exactly once at $(j,y)$, uniformly for $|y|\leq B$.
\item Uniformly for these sites and levels,
\begin{equation}\label{eq:arrival-logarithm}
 T_\theta(j,y)=\frac{j}{c_*}
       +\frac{d+2}{2\lambda_*c_*}\log j+O(1)
 \qquad(j\to\infty).
\end{equation}
\item Writing $r(j,y)=(j,y)\bmod\Gamma$, one has
\begin{align}
 T_{\theta_2}(j,y)-T_{\theta_1}(j,y)
  &=\frac{\xi_{\theta_1,r(j,y)}-\xi_{\theta_2,r(j,y)}}{c_*}+o(1),
       \label{eq:arrival-level-gap}\\
 T_\theta(j+L_1,y)-T_\theta(j,y)&=\frac{L_1}{c_*}+o(1),
       \label{eq:arrival-cell-gap}
\end{align}
uniformly as $j\to\infty$, where
$\theta_-\leq\theta_1\leq\theta_2\leq\theta_+$.
\end{enumerate}

\label{conj:general-periodic}
Under \eqref{eq:periodic-kpp}--\eqref{eq:u0}, for every fixed
$\theta\in(0,1)$, $e\in\mathbb S^{d-1}$ and $\rho\geq\sqrt d$,
\begin{equation}\label{eq:general-target}
 R_{\theta,e,\rho}(t)=w(e)t-
               \frac{d+2}{2p_e\cdot e}\log t+O(1).
\end{equation}

\label{thm:Dirichlet-quotient}
Assume \eqref{eq:periodic-kpp}--\eqref{eq:u0}, and choose
\begin{equation}\label{eq:quotient-K}
 K\geq\max\left\{1,\max_{x\in\mathcal C}a(x),K_F\right\}.
\end{equation}
For every decreasing domain and initial datum described above,
\begin{equation}\label{eq:Dirichlet-quotient-bound}
 u(t,x)\geq\frac{v(t,x)^2}{v(t,x)+KJ_v(t,x)}
       \qquad(t\geq0,\ x\in\mathbb Z^d),
\end{equation}
where the quotient is zero when its denominator vanishes.

\label{lem:Dirichlet-bridge}
The weights $\mathfrak b_{t,x}(s,\cdot)$ sum to one and are consistent
with these backward kernels. Moreover,
\begin{equation}\label{eq:normalized-potential-identity}
 \frac{J_v(t,x)}{v(t,x)^2}
  =\int_0^t\sum_y\mathfrak b_{t,x}(s,y)
                   \frac{v(s,y)}{v(t,x)}\,\mathrm d s.
\end{equation}

\label{prop:general-lower-criterion}
Assume \eqref{eq:periodic-kpp}--\eqref{eq:u0}. Suppose that, for some
$m,C_*,R,t_0>0$, every $t\geq t_0$ admits $x_t\in D(t)$ with
\begin{equation}\label{eq:criterion-seed-inputs}
 |x_t-m_e^T(t)e|\leq R,\qquad v(t,x_t)\geq m,\qquad
 J_v(t,x_t)\leq C_*v(t,x_t)^2.
\end{equation}
For every $\theta\in(0,1)$ and finite $\rho\geq0$, there are
$C,t_1>0$ such that
\begin{equation}\label{eq:criterion-inner-tube}
 u(t,x)\geq\theta
 \quad\hbox{if }t\geq t_1,\quad |x-re|\leq\rho,\quad
                     0\leq r\leq m_e^T(t)-C.
\end{equation}
Consequently, \eqref{eq:general-target} holds for $\rho\geq\sqrt d$.
